cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

const origin = 'JFK';
const destination = 'SFO';
const date = '2026-09-15';

// Step 1: Find all flights from JFK on 2026-09-15
const fromJFK = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin=?\").all(origin);

const leg1Flights = [];
fromJFK.forEach(f => {
    const dates = JSON.parse(f.dates_json || '{}');
    if (dates[date] && dates[date].status === 'available') {
        leg1Flights.push({
            flight_number: f.flight_id,
            origin: f.origin,
            destination: f.destination,
            departure_time: f.departure_time,
            arrival_time: f.arrival_time,
            available_seats: dates[date].available_seats,
            prices: dates[date].prices
        });
    }
});

console.log('=== LEG 1: Flights from ' + origin + ' on ' + date + ' ===');
console.log(JSON.stringify(leg1Flights, null, 2));

// Step 2: For each leg1 flight, find connecting flights to SFO
const results = [];
leg1Flights.forEach(leg1 => {
    const connectingCity = leg1.destination;

    // Check same day and next day for connections
    const datesToCheck = [date, '2026-09-16'];

    datesToCheck.forEach(d => {
        const fromConnect = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin=? AND destination=?\").all(connectingCity, destination);

        fromConnect.forEach(f => {
            const dates = JSON.parse(f.dates_json || '{}');
            if (dates[d] && dates[d].status === 'available') {
                // Check that leg2 departs after leg1 arrives (if same day)
                const canConnect = (d !== date) || (f.departure_time === null || leg1.arrival_time === null || f.departure_time >= leg1.arrival_time);
                if (canConnect) {
                    results.push({
                        leg1: leg1,
                        leg2: {
                            flight_number: f.flight_id,
                            origin: f.origin,
                            destination: f.destination,
                            date: d,
                            departure_time: f.departure_time,
                            arrival_time: f.arrival_time,
                            available_seats: dates[d].available_seats,
                            prices: dates[d].prices
                        },
                        connecting_city: connectingCity
                    });
                }
            }
        });
    });
});

console.log('\n=== ONE-STOP FLIGHT RESULTS: ' + origin + ' -> ' + destination + ' on ' + date + ' ===');
console.log(JSON.stringify(results, null, 2));
console.log('\nTotal one-stop options found: ' + results.length);

// Also check what flies out of MIA (the only JFK destination)
console.log('\n=== ALL FLIGHTS FROM MIA (tau2Airline) ===');
const fromMIA = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='MIA'\").all();
console.log('Count:', fromMIA.length);
fromMIA.forEach(f => {
    const dates = JSON.parse(f.dates_json || '{}');
    console.log(f.flight_id, f.origin, '->', f.destination, 'dates:', Object.keys(dates).join(', '));
});
"

