const Database = require('better-sqlite3');
const db = new Database('world.db');

const date = '2026-09-15';

// Leg 1: LAX -> SFO on 2026-09-15
console.log('=== LEG 1: LAX -> SFO on ' + date + ' ===');
const leg1Flights = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='LAX' AND destination='SFO'\").all();

const leg1Available = [];
leg1Flights.forEach(f => {
    const dates = JSON.parse(f.dates_json || '{}');
    if (dates[date] && dates[date].status === 'available') {
        const info = {
            flight_number: f.flight_id,
            origin: f.origin,
            destination: f.destination,
            departure_time: f.departure_time,
            arrival_time: f.arrival_time,
            available_seats: dates[date].available_seats,
            prices: dates[date].prices
        };
        leg1Available.push(info);
        console.log(JSON.stringify(info, null, 2));
    }
});
console.log('Leg 1 options:', leg1Available.length);

// Leg 2: SFO -> SEA on 2026-09-15 (and 2026-09-16 in case of next-day connection)
console.log('\n=== LEG 2: SFO -> SEA on ' + date + ' and 2026-09-16 ===');
const leg2Flights = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline' AND origin='SFO' AND destination='SEA'\").all();

const leg2Available = {};
['2026-09-15', '2026-09-16'].forEach(d => {
    leg2Available[d] = [];
    leg2Flights.forEach(f => {
        const dates = JSON.parse(f.dates_json || '{}');
        if (dates[d] && dates[d].status === 'available') {
            const info = {
                flight_number: f.flight_id,
                origin: f.origin,
                destination: f.destination,
                date: d,
                departure_time: f.departure_time,
                arrival_time: f.arrival_time,
                available_seats: dates[d].available_seats,
                prices: dates[d].prices
            };
            leg2Available[d].push(info);
            console.log(JSON.stringify(info, null, 2));
        }
    });
});

// Build one-stop combinations
console.log('\n=== ONE-STOP COMBINATIONS: LAX -> SFO -> SEA ===');
const combinations = [];
leg1Available.forEach(leg1 => {
    ['2026-09-15', '2026-09-16'].forEach(d => {
        leg2Available[d].forEach(leg2 => {
            // If same day, ensure leg2 departs after leg1 arrives
            if (d === date && leg1.arrival_time && leg2.departure_time) {
                if (leg2.departure_time < leg1.arrival_time) return;
            }
            combinations.push({ leg1, leg2, connecting_city: 'SFO' });
        });
    });
});

console.log(JSON.stringify(combinations, null, 2));
console.log('Total combinations:', combinations.length);

// User check
const user = db.prepare(\"SELECT user_id, name FROM users WHERE user_id = 'E002'\").get();
console.log('\n=== USER E002 ===');
console.log(user ? JSON.stringify(user) : 'NOT FOUND');
"

